SELECT  json_build_object('aggregate', json_build_object('count', COUNT(*), 'sum', json_build_object('id', sum("_root"."root.pg.id" ) ), 'avg', json_build_object('id', avg("_root"."root.pg.id" ) ), 'min', json_build_object('id', min("_root"."root.pg.id" ) ), 'max', json_build_object('id', max("_root"."root.pg.id" ) ) ), 'nodes', coalesce(json_agg("root.f.nodes" ), '[]' ) ) AS "root" FROM  (SELECT  "_root.base"."id" AS "root.pg.id", row_to_json((SELECT  "_e"  FROM  (SELECT  "_root.base"."id" AS "id"       ) AS "_e"      ) ) AS "root.f.nodes" FROM  (SELECT  *  FROM "public"."article"  WHERE (("public"."article"."id") < (('0')::integer))     ) AS "_root.base"      ) AS "_root"
